
namespace Stateless {
    
    /// <summary>
    ///   A class for looking up localized strings, etc.
    /// </summary>
   
    internal class ParameterConversionResources {
        
      
 
        /// <summary>
        ///   Looks up a localized string similar to An argument of type {0} is required in position {1}..
        /// </summary>
        internal static string ArgOfTypeRequiredInPosition {
            get {
                return "An argument of type {0} is required in position {1}.";
            }
        }
        
        /// <summary>
        ///   Looks up a localized string similar to Too many parameters have been supplied. Expecting {0} but got {1}..
        /// </summary>
        internal static string TooManyParameters {
            get {
                return "Too many parameters have been supplied. Expecting {0} but got {1}.";
            }
        }
        
        /// <summary>
        ///   Looks up a localized string similar to The argument in position {0} is of type {1} but must be of type {2}..
        /// </summary>
        internal static string WrongArgType {
            get {
                return "The argument in position {0} is of type {1} but must be of type {2}.";
            }
        }
    }
}
